	var want = newest ? runnerKey(newest.nonce, r.seq, r.commit) : '';
	A.live().forEach(function (a) {
		if (a.diamond === A.RUNNER && a.key.indexOf(RUNNER_KEY) === 0 && a.key !== want) A.clear(A.RUNNER, a.key);
	});
